    # 获取 YAML 有效负载作为查询参数
    yaml_payload = request.args.get('payload')

    if not yaml_payload:
        return "Error: No payload provided", 400

    try:
        # 解析 YAML 有效负载
        data = yaml.safe_load(yaml_payload)

        # 提取产品代码和数量
        product_code = data.get('product_code')
        quantity = data.get('quantity')

        if not product_code or not quantity:
            return "Error: Missing product_code or quantity", 400

        # 假设价格是固定的，这里用一个简单的映射来模拟
        # 实际应用中，价格可能来自数据库或外部服务
        prices = {
            'A001': 10.0,
            'A002': 15.5,
            'A003': 20.0
        }

        # 计算总价
        price = prices.get(product_code)
        if price is None:
            return f"Error: Product code {product_code} not found", 400

        total_price = price * quantity

        # 将总价格作为字符串返回
        return str(total_price)

    except yaml.YAMLError as e:
        return f"Error: Invalid YAML format - {e}", 400
