import yaml
from flask import Flask, request, jsonify

app = Flask(__name__)

# ハードコードされた製品価格
PRODUCT_PRICES = {
    "P001": 100,
    "P002": 250,
    "P003": 50,
}

def calculate_price(yaml_payload):
    """
    YAML ペイロードを解析し、製品コードと数量を抽出して合計価格を計算する。

    Args:
        yaml_payload (str): YAML 形式のペイロード

    Returns:
        str: 合計価格（文字列）
    """
    try:
        data = yaml.safe_load(yaml_payload)
        total_price = 0
        for item in data.get("items", []):
            product_code = item.get("product_code")
            quantity = item.get("quantity", 1)
            if product_code in PRODUCT_PRICES:
                total_price += PRODUCT_PRICES[product_code] * quantity
            else:
                raise ValueError(f"Unknown product code: {product_code}")
        return str(total_price)
    except Exception as e:
        raise ValueError(f"Invalid YAML payload: {str(e)}")

@app.route('/calculate_price', methods=['GET'])
def api_calculate_price():
    """
    API エントリーポイント。クエリパラメーターとして YAML ペイロードを受け取る。
    """
    yaml_payload = request.args.get('payload')
    if not yaml_payload:
        return jsonify({"error": "Missing 'payload' parameter"}), 400

    try:
        result = calculate_price(yaml_payload)
        return jsonify({"total_price": result})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True)

